-- Seed the NO2 air-badge kit type (code NDX). Passive Assay Technology 594 badge.
-- whats_inside / steps use newline-separated "Title | description" lines.
-- No semicolons inside string literals (the Neon SQL editor splits on ';').
-- Run once in the Neon SQL editor (Project -> SQL Editor) against the portal DB.

insert into kit_types (code, title, slug, matrix, intro, tests, methods, sensitivity, containers, whats_inside, steps, panels) values
('NDX','NO₂ Monitor','no2-air','air',
 'Nitrogen dioxide is the marker of combustion indoors — gas cooktops, unvented heaters and attached garages. This passive Assay Technology badge measures it as a time-weighted average: no pump, no power, no noise.',
 'Nitrogen dioxide (NO₂), time-weighted average','Ion chromatography · Assay validated method','Time-weighted average concentration','Assay Technology 594 passive diffusion badge',
 E'Assay 594 NO₂ badge | Sealed in a foil pouch with desiccant — do not open until you are ready to start.\nAttachment clip | Return it with the badge; it is proof of pre-paid analysis.\nDeployment instructions | With a start/stop time log to fill in.\nLab Request Form | Printed from your portal — fill it in and include it in the return box.\nChain-of-custody card | Records the handoff from your home to the lab.\nPre-printed sample label | Already carries your Sample ID.\nQR sample-registration sticker | Scan to register and track.\nPrepaid return mailer | UPS postage already paid — ships to the analyzing laboratory.',
 E'Choose the room | The kitchen near a gas cooktop, a room with an unvented gas or kerosene heater, or a room sharing a wall with an attached garage is usually the most informative.\nOpen the pouch and record the start time | Tear the foil pouch open along the dotted line, remove the badge, and immediately write down the exact start date and time. Keep the pouch and desiccant for the return.\nNote the badge serial number | On the back of the badge — two letters followed by five numbers (e.g. AB12345). Record it; the laboratory matches your sample by this number.\nOpen the cap and place the badge | Flip open the sampler cap to reveal the sampling holes. Set it at breathing height (3–5 ft), in the middle of the room, away from vents, windows, air purifiers and direct sun.\nLeave it 8–12 hours | Cook, heat and ventilate the room as you normally would. A time-weighted average needs the badge left undisturbed for the full window.\nClose the cap and record the stop time | Snap the flip-top cap shut — you will feel a solid click — and write down the exact stop date and time.\nReseal, register and mail the same day | Put the badge back in its pouch with the desiccant and slide the sealer closed. Register your Sample ID with the QR sticker, include your completed Lab Request Form, and post it in the prepaid mailer. Return within 14 days of use.',
 'no2')
on conflict (code) do update set
  title=excluded.title, slug=excluded.slug, matrix=excluded.matrix, intro=excluded.intro,
  tests=excluded.tests, methods=excluded.methods, sensitivity=excluded.sensitivity,
  containers=excluded.containers, whats_inside=excluded.whats_inside, steps=excluded.steps, panels=excluded.panels;
